def get_alpha191_formula(number: int) -> str:
    """获取指定编号的Alpha191因子公式"""
    if number < 1 or number > 191:
        raise ValueError("Alpha191 编号必须在 1-191 之间")
    formula = ALPHA191_FORMULAS.get(number, "")
    if not formula:
        raise ValueError(f"Alpha#{number} 暂未实现")
    return formula

